from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


class Group:
    def __init__(self, members: list[str]) -> None:
        if not members or len(set(members)) != len(members):
            raise ValueError("Members must be nonempty and unique")
        self._members = list(members)
        self._balances = {member: 0 for member in members}  # Cents

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        if payer not in self._balances:
            raise ValueError("Payer must be a group member")

        try:
            value = Decimal(str(amount))
            if not value.is_finite() or value <= 0:
                raise ValueError("Amount must be positive and finite")
            cents = int((value * 100).to_integral_value(rounding=ROUND_HALF_UP))
        except (InvalidOperation, TypeError) as exc:
            raise ValueError("Invalid amount") from exc

        people = self._members if participants is None else participants
        if not people or len(set(people)) != len(people):
            raise ValueError("Participants must be nonempty and unique")
        if any(person not in self._balances for person in people):
            raise ValueError("Participants must be group members")

        share = cents // len(people)
        for person in people:
            if person != payer:
                self._balances[person] -= share
                self._balances[payer] += share

    def balances(self) -> dict[str, float]:
        return {member: cents / 100 for member, cents in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        remaining = self._balances.copy()
        payments = []

        while True:
            debtor = min(remaining, key=remaining.get)
            creditor = max(remaining, key=remaining.get)
            amount = min(-remaining[debtor], remaining[creditor])
            if amount < 100:
                break

            payments.append ( (debtor, creditor, amount / 100))
            remaining[debtor] += amount
            remaining[creditor] -= amount

        return payments
